  const v = trimmed.toLowerCase();
  if (v !== "native" && v !== "sqlite-rag") {
    console.error("extractor must be one of: native, sqlite-rag");
    process.exit(1);
  }
  manager.updateProjectSetting("rag", {
    ...(project.rag || {}),
    extractor: v as "native" | "sqlite-rag",
  });
  break;
}
case "project.rag.python": {
  manager.updateProjectSetting("rag", { ...(project.rag || {}), python: trimmed });
  break;
}

update_md5_171e8949e81a3f8b48d4b9f4ebcc3.content_md5_171e8949e81a3f8b48d4b9f4ebcc:
#!/usr/bin/env python3
import argparse
import sys
from pathlib import Path
from typing import Optional


def extract_with_sqlite_rag(p: Path, max_bytes: Optional[int]) -> str:
    from sqlite_rag.reader import FileReader

    return FileReader.parse_file(p, max_document_size_bytes=max_bytes)


def extract_with_markitdown(p: Path, max_bytes: Optional[int]) -> str:
    from markitdown import MarkItDown, StreamInfo

    converter = MarkItDown()
    text = converter.convert(p, stream_info=StreamInfo(charset="utf8")).text_content

    b = text.encode("utf-8", errors="ignore")
    if max_bytes:
        b = b[:max_bytes]

    return b.decode("utf-8", errors="ignore")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--path", required=True)
    ap.add_argument("--max-bytes", type=int, default=0)
    args = ap.parse_args()

    p = Path(args.path)
    if not p.exists():
        print(f"File not found: {p}", file=sys.stderr)
        return 2

    max_bytes: Optional[int] = args.max_bytes if args.max_bytes and args.max_bytes > 0 else None

    try:
        try:
            text = extract_with_sqlite_rag(p, max_bytes)
        except Exception:
            text = extract_with_markitdown(p, max_bytes)

        sys.stdout.write(text or "")
        return 0

    except ImportError as e:
        print(
            "Missing Python dependency. Install one of: sqlite-rag (recommended), markitdown",
            file=sys.stderr,
        )
        print(str(e), file=sys.stderr)
        return 3
    except Exception as e:
        print(f"Extraction failed: {e}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
